function [a] = de_sitter(r, v, earth_helio_pos, earth_helio_vel, gamma)
%DE_SITTER  relativity.deSitter(rSat, vSat, earthHelioPos, earthHelioVel, gamma): the geodesic precession, from the Earth's
%   position and velocity relative to the Sun [m, m/s].
%   r: real[1][3] (passed a plain number)
%   v: real[1][3] (passed a plain number)
%   earth_helio_pos: real[1][3] (passed a plain number)
%   earth_helio_vel: real[1][3] (passed a plain number)
%   gamma: real[1] (passed a plain number)
%   returns a: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    a = zeros(3, 1);
    k = asils.models.de440.de440_constants();
    c = k.c;
    gms = k.gm_sun;
    den = ((c * c) * asils.pc.pow_(asils.pc.norm_(earth_helio_pos), 3));
    ae = [(((-(gms)) * earth_helio_pos(1)) / den); (((-(gms)) * earth_helio_pos(2)) / den); (((-(gms)) * earth_helio_pos(3)) / den)];
    w = asils.pc.cross_(asils.pc.cross_(earth_helio_vel, ae), v);
    g = (1 + (2 * gamma));
    a = [(g * w(1)); (g * w(2)); (g * w(3))];
end
